<?php require __DIR__.'/../header.php';require __DIR__.'/../navbar.php';?><main class="container-fluid py-4 px-lg-4"><div class="col-md-8 col-xl-6"><h2>Registrar pago</h2><?php if(!$asignaciones):?><div class="alert alert-warning">No hay campañas asignadas disponibles.</div><?php else:?><form method="post" class="card p-4"><div class="mb-3"><label class="form-label">Vendedor y campaña</label><select class="form-select" name="asignacion_id" required><?php foreach($asignaciones as $a):?><option value="<?=$a['id']?>"><?=e($a['vendedor'])?> — <?=e($a['campania'])?></option><?php endforeach;?></select></div><div class="row g-3"><div class="col-md-6"><label class="form-label">Fecha</label><input class="form-control" type="date" name="fecha_pago" value="<?=date('Y-m-d')?>" required></div><div class="col-md-6"><label class="form-label">Monto</label><input class="form-control" type="number" min="0.01" step="0.01" name="monto" required></div><div class="col-md-6"><label class="form-label">Medio de pago</label><select class="form-select" name="medio_pago"><option value="EFECTIVO">Efectivo</option><option value="TRANSFERENCIA">Transferencia</option><option value="OTRO">Otro</option></select></div><div class="col-12"><label class="form-label">Observación</label><textarea class="form-control" name="observacion"></textarea></div></div><div class="mt-4"><button class="btn btn-primary">Guardar pago</button><a class="btn btn-light" href="index.php?c=pago&a=inicio">Cancelar</a></div></form><?php endif;?></div></main><?php require __DIR__.'/../footer.php';?>
